// notification.dto.ts
export interface SendNotificationDto {
  userId: string;
  channels: string[]; // e.g. ['push', 'email', 'sms']
  payload: Record<string, unknown>;
}

interface NotificationJobData {
  userId: string;
  channels: string[];
  payload: Record<string, unknown>;
}

// notification.producer.ts
import { Injectable } from '@nestjs/common';
import { InjectQueue } from '@nestjs/bullmq';
import { Queue } from 'bullmq';

@Injectable()
export class NotificationProducer {
  constructor(@InjectQueue('notification') private readonly notificationQueue: Queue) {}

  async enqueue(dto: SendNotificationDto): Promise<void> {
    // BUG: the whole channels array is bundled into the DATA of ONE job.
    // The broker's unit of retry is this single job, not an individual channel.
    await this.notificationQueue.add(
      'send-notification',
      {
        userId: dto.userId,
        channels: dto.channels,
        payload: dto.payload,
      },
      {
        attempts: 3,
        backoff: { type: 'exponential', delay: 2000 },
      },
    );
  }
}

// channel-dispatcher.ts
import { Injectable } from '@nestjs/common';
import { PushSender } from './push-sender';
import { EmailSender } from './email-sender';
import { SmsSender } from './sms-sender';

@Injectable()
export class ChannelDispatcher {
  constructor(
    private readonly pushSender: PushSender,
    private readonly emailSender: EmailSender,
    private readonly smsSender: SmsSender,
  ) {}

  async send(channel: string, userId: string, payload: Record<string, unknown>): Promise<void> {
    switch (channel) {
      case 'push':
        return this.pushSender.send(userId, payload); // succeeds
      case 'email':
        return this.emailSender.send(userId, payload); // THROWS on first attempt (e.g. SMTP timeout)
      case 'sms':
        return this.smsSender.send(userId, payload);
      default:
        throw new Error(`Unknown channel: ${channel}`);
    }
  }
}

// notification.processor.ts
import { Injectable } from '@nestjs/common';
import { Processor, WorkerHost } from '@nestjs/bullmq';
import { Job } from 'bullmq';
import { ChannelDispatcher } from './channel-dispatcher';

@Injectable()
@Processor('notification')
export class NotificationProcessor extends WorkerHost {
  constructor(private readonly dispatcher: ChannelDispatcher) {
    super();
  }

  async process(job: Job<NotificationJobData>): Promise<void> {
    // BUG: no try/catch, no per-channel idempotency guard.
    // channels[0] (push) sends fine, channels[1] (email) throws,
    // the throw bubbles out of process() so BullMQ marks the WHOLE job
    // 'failed' and retries it from the top -> push gets re-sent.
    for (const channel of job.data.channels) {
      await this.dispatcher.send(channel, job.data.userId, job.data.payload);
    }
  }
}
